import heapq


def k_machine_schedule(jobs: list[list[int]], k: int) -> int:
    if not jobs or k <= 0:
        return 0
    if k >= len(jobs):
        return sum(pay for _, _, pay in jobs)

    coords = sorted({t for s, e, _ in jobs for t in (s, e)})
    pos = {t: i for i, t in enumerate(coords)}
    m = len(coords)

    adj: list[list[list[int]]] = [[] for _ in range(m)]

    def add_edge(u: int, v: int, cap: int, cost: int) -> None:
        adj[u].append([v, cap, cost, len(adj[v])])
        adj[v].append([u, 0, -cost, len(adj[u]) - 1])

    for i in range(m - 1):
        add_edge(i, i + 1, k, 0)

    for start, end, pay in jobs:
        add_edge(pos[start], pos[end], 1, -pay)

    INF = 10**18
    h = [INF] * m
    h[0] = 0
    for u in range(m):
        hu = h[u]
        for v, cap, cost, _ in adj[u]:
            if cap > 0 and hu + cost < h[v]:
                h[v] = hu + cost

    total_cost = 0
    remaining = k
    sink = m - 1

    while remaining > 0:
        dist = [INF] * m
        parent_node = [-1] * m
        parent_edge = [-1] * m
        dist[0] = 0
        pq = [(0, 0)]

        while pq:
            d, u = heapq.heappop(pq)
            if d != dist[u]:
                continue
            hu = h[u]
            for edge_idx, (v, cap, cost, _) in enumerate(adj[u]):
                if cap > 0:
                    nd = d + cost + hu - h[v]
                    if nd < dist[v]:
                        dist[v] = nd
                        parent_node[v] = u
                        parent_edge[v] = edge_idx
                        heapq.heappush(pq, (nd, v))

        if dist[sink] == INF:
            break

        for i in range(m):
            if dist[i] < INF:
                h[i] += dist[i]

        if h[sink] >= 0:
            break

        flow = remaining
        v = sink
        while v != 0:
            u = parent_node[v]
            cap = adj[u][parent_edge[v]][1]
            if cap < flow:
                flow = cap
            v = u

        v = sink
        while v != 0:
            u = parent_node[v]
            edge = adj[u][parent_edge[v]]
            edge[1] -= flow
            adj[v][edge[3]][1] += flow
            v = u

        remaining -= flow
        total_cost += flow * h[sink]

    return -total_cost
